نقش سازمانی: مدیر تولید معدن (mining_production_manager)

درخواست کاربر:
هزینهٔ هر تن این ماه نسبت به ماه قبل 16٪ بالا رفته در حالی که نرخ سوخت تغییری نداشته. دقیقاً کجای زنجیرهٔ هزینه شکسته؟ (مدیر تولید معدن — معدن روی مهدی‌آباد)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "cost_ledger",
      "description": "هزینهٔ عملیاتی به تفکیک جزء (سوخت، قطعات، دستمزد، پیمانکار)",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "toman_per_ton"
      ]
    },
    {
      "dataset": "haul_report",
      "description": "گزارش حمل: مسافت، تن-کیلومتر و مصرف سوخت کامیون‌ها",
      "dimensions": [
        "route",
        "period"
      ],
      "measures": [
        "distance_km",
        "tons",
        "liter"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_ton",
      "description": "هزینهٔ عملیاتی هر تن",
      "formula": "هزینهٔ کل / تن فرآوری‌شده",
      "unit": "تومان بر تن",
      "dimensions": [
        "component",
        "period"
      ]
    },
    {
      "metric": "fuel_per_ton",
      "description": "مصرف سوخت به‌ازای هر تن",
      "formula": "لیتر مصرفی / تن",
      "unit": "لیتر بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود",
    "تأمین مالی عملیات از محل فروش کنسانتره و تسهیلات بانکی"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "cost_per_ton"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "cost_per_ton_toman": {
    "prev_month": 69000,
    "curr_month": 80000,
    "change": 11000
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "cost_ledger",
    "filters": {
      "period": "curr_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "components_toman_per_ton": {
    "سوخت": 6440,
    "قطعات و لاستیک": 3192,
    "دستمزد و پیمانکار": 1368
  },
  "share_of_fuel_in_rise_pct": 59
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "haul_report",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "fuel_liter_per_ton": {
    "prev_month": 2.24,
    "curr_month": 3.16
  },
  "haul_distance_km": {
    "prev_month": 3.8,
    "curr_month": 6.1,
    "note": "پیشروی پیت به عمق و جابه‌جایی دامپ به فاصلهٔ دورتر"
  }
}

نقش سازمانی: مدیر تولید معدن (mining_production_manager)

درخواست کاربر:
عیار سنگ سه ماه است پایین آمده و زمین‌شناس می‌گوید ذخیره رو به اتمام است و باید برای کاهش تولید برنامه‌ریزی کنیم. این نتیجه‌گیری چقدر معتبر است؟ (مدیر تولید معدن — معدن روی مهدی‌آباد)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "grade_control",
      "description": "عیار سنگ خوراک به تفکیک پیت و ماه",
      "dimensions": [
        "pit",
        "month"
      ],
      "measures": [
        "grade_pct"
      ]
    },
    {
      "dataset": "production_plan_actual",
      "description": "برنامه و واقعی استخراج به تفکیک پیت و هفته",
      "dimensions": [
        "pit",
        "week"
      ],
      "measures": [
        "plan_tons",
        "actual_tons"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ore_grade",
      "description": "عیار سنگ خوراک",
      "formula": "وزن فلز مفید / وزن سنگ",
      "unit": "درصد",
      "dimensions": [
        "pit",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود",
    "تأمین مالی عملیات از محل فروش کنسانتره و تسهیلات بانکی"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "ore_grade",
    "granularity": "month",
    "range": "last_3_months"
  }
}

TOOL_OBSERVATION:
{
  "grade_monthly": [
    {
      "month": "خرداد",
      "grade_pct": 0.85
    },
    {
      "month": "تیر",
      "grade_pct": 0.8
    },
    {
      "month": "مرداد",
      "grade_pct": 0.75
    }
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "production_plan_actual",
    "filters": {
      "period": "next_quarter"
    }
  }
}

