        "equipment",
        "reason",
        "period"
      ],
      "measures": [
        "hours"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "extraction_rate",
      "description": "نرخ استخراج",
      "formula": "تن استخراج‌شده / روزهای کاری",
      "unit": "تن در روز",
      "dimensions": [
        "pit",
        "period"
      ]
